SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS tenants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,status VARCHAR(32) NOT NULL DEFAULT 'active',plan_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,email VARCHAR(254) NOT NULL,name VARCHAR(160) NOT NULL,password_hash TEXT NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',is_owner BOOLEAN NOT NULL DEFAULT FALSE,is_super_admin BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_users_tenant_email(tenant_id,email),UNIQUE KEY uq_users_email(email),CONSTRAINT fk_users_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS roles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,code VARCHAR(100) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_roles_tenant_code(tenant_id,code),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(140) NOT NULL UNIQUE,description TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,tenant_id BIGINT UNSIGNED NOT NULL,token_hash VARCHAR(255) NOT NULL UNIQUE,expires_at DATETIME(6) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_sessions_exp(expires_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exchange_accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,exchange VARCHAR(40) NOT NULL DEFAULT 'binance',label VARCHAR(120) NOT NULL,account_uid VARCHAR(120) NOT NULL DEFAULT '',p2p_nickname VARCHAR(160) NOT NULL DEFAULT '',api_key_ciphertext LONGTEXT NOT NULL,api_secret_ciphertext LONGTEXT NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',last_sync_at DATETIME(6) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_exchange_label(tenant_id,exchange,label),KEY idx_exchange_tenant(tenant_id,status),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exchange_account_permissions (tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,exchange_account_id BIGINT UNSIGNED NOT NULL,permission_code VARCHAR(140) NOT NULL,PRIMARY KEY(user_id,exchange_account_id,permission_code),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(exchange_account_id) REFERENCES exchange_accounts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,exchange_account_id BIGINT UNSIGNED NOT NULL,external_order_no VARCHAR(100) NOT NULL,status VARCHAR(60) NOT NULL,trade_type VARCHAR(16) NOT NULL DEFAULT '',asset VARCHAR(32) NOT NULL DEFAULT '',fiat VARCHAR(32) NOT NULL DEFAULT '',price DECIMAL(28,12) NOT NULL DEFAULT 0,amount DECIMAL(28,12) NOT NULL DEFAULT 0,total DECIMAL(28,12) NOT NULL DEFAULT 0,counterparty_name VARCHAR(160) NOT NULL DEFAULT '',assigned_user_id BIGINT UNSIGNED NULL,raw_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_orders_external(tenant_id,exchange_account_id,external_order_no),KEY idx_orders_tenant_status(tenant_id,status,updated_at),KEY idx_orders_account_status(exchange_account_id,status,updated_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(exchange_account_id) REFERENCES exchange_accounts(id) ON DELETE CASCADE,FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS advertisements (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,exchange_account_id BIGINT UNSIGNED NOT NULL,external_adv_no VARCHAR(100) NOT NULL,status VARCHAR(32) NOT NULL,trade_type VARCHAR(16) NOT NULL DEFAULT '',asset VARCHAR(32) NOT NULL DEFAULT '',fiat VARCHAR(32) NOT NULL DEFAULT '',price DECIMAL(28,12) NOT NULL DEFAULT 0,surplus_amount DECIMAL(28,12) NOT NULL DEFAULT 0,raw_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ads_external(tenant_id,exchange_account_id,external_adv_no),KEY idx_ads_tenant(tenant_id,status,updated_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(exchange_account_id) REFERENCES exchange_accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chats (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,exchange_account_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,external_message_id VARCHAR(120) NOT NULL DEFAULT '',external_uuid VARCHAR(120) NOT NULL DEFAULT '',message_type VARCHAR(32) NOT NULL DEFAULT 'text',content LONGTEXT NOT NULL,image_url LONGTEXT NOT NULL,sender_name VARCHAR(160) NOT NULL DEFAULT '',is_self BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(32) NOT NULL DEFAULT 'unread',sent_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_chats_order(tenant_id,order_id,sent_at,id),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(exchange_account_id) REFERENCES exchange_accounts(id) ON DELETE CASCADE,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chat_read_states (tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,last_read_chat_id BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,order_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,method_identifier VARCHAR(100) NOT NULL,account_name VARCHAR(180) NOT NULL DEFAULT '',account_number VARCHAR(180) NOT NULL DEFAULT '',bank_name VARCHAR(180) NOT NULL DEFAULT '',details_json JSON NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_payment_tenant(tenant_id,status),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS routing_rules (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,priority INT NOT NULL DEFAULT 100,enabled BOOLEAN NOT NULL DEFAULT TRUE,conditions_json JSON NOT NULL,actions_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ledger_accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,code VARCHAR(80) NOT NULL,name VARCHAR(180) NOT NULL,account_type VARCHAR(40) NOT NULL,currency VARCHAR(20) NOT NULL DEFAULT 'USDT',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_ledger_account(tenant_id,code),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ledger_transactions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,reference_type VARCHAR(60) NOT NULL DEFAULT '',reference_id VARCHAR(120) NOT NULL DEFAULT '',description TEXT NOT NULL,posted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ledger_entries (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,transaction_id BIGINT UNSIGNED NOT NULL,account_id BIGINT UNSIGNED NOT NULL,direction ENUM('debit','credit') NOT NULL,amount DECIMAL(28,12) NOT NULL,currency VARCHAR(20) NOT NULL DEFAULT 'USDT',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_ledger_tx(tenant_id,transaction_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(transaction_id) REFERENCES ledger_transactions(id) ON DELETE CASCADE,FOREIGN KEY(account_id) REFERENCES ledger_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,kind VARCHAR(80) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,data_json JSON NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_notifications_user(tenant_id,user_id,is_read,created_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NULL,action VARCHAR(140) NOT NULL,entity_type VARCHAR(100) NOT NULL DEFAULT '',entity_id VARCHAR(120) NOT NULL DEFAULT '',ip_address VARCHAR(80) NOT NULL DEFAULT '',user_agent TEXT NOT NULL,metadata_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_audit_tenant_time(tenant_id,created_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS plans (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,monthly_price DECIMAL(18,2) NOT NULL DEFAULT 0,setup_fee DECIMAL(18,2) NOT NULL DEFAULT 0,max_users BIGINT NOT NULL DEFAULT 5,max_exchange_accounts BIGINT NOT NULL DEFAULT 2,entitlements_json JSON NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS subscriptions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,plan_id BIGINT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',provider VARCHAR(60) NOT NULL DEFAULT 'manual',provider_subscription_id VARCHAR(180) NOT NULL DEFAULT '',current_period_start DATETIME(6) NULL,current_period_end DATETIME(6) NULL,cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_subscriptions_tenant(tenant_id,status),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(plan_id) REFERENCES plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,subscription_id BIGINT UNSIGNED NULL,invoice_type VARCHAR(32) NOT NULL DEFAULT 'monthly',currency VARCHAR(20) NOT NULL DEFAULT 'BDT',amount DECIMAL(18,2) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL DEFAULT 'pending',due_at DATETIME(6) NULL,paid_at DATETIME(6) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NULL,provider VARCHAR(60) NOT NULL,provider_payment_id VARCHAR(180) NOT NULL DEFAULT '',amount DECIMAL(18,2) NOT NULL DEFAULT 0,currency VARCHAR(20) NOT NULL DEFAULT 'BDT',status VARCHAR(32) NOT NULL DEFAULT 'pending',raw_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS approvals (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,requested_by BIGINT UNSIGNED NULL,approved_by BIGINT UNSIGNED NULL,kind VARCHAR(100) NOT NULL,payload_json JSON NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS proofs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,uploaded_by BIGINT UNSIGNED NULL,file_key TEXT NOT NULL,file_name TEXT NOT NULL,mime_type VARCHAR(120) NOT NULL DEFAULT '',size_bytes BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS activity_sessions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,started_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),last_heartbeat_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),ended_at DATETIME(6) NULL,status VARCHAR(32) NOT NULL DEFAULT 'online',FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS extension_tasks (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,exchange_account_id BIGINT UNSIGNED NULL,task_type VARCHAR(100) NOT NULL,payload_json JSON NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending',attempt_count INT NOT NULL DEFAULT 0,result_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,FOREIGN KEY(exchange_account_id) REFERENCES exchange_accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS outbox_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NULL,topic VARCHAR(140) NOT NULL,event_key VARCHAR(180) NOT NULL DEFAULT '',payload_json JSON NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending',attempt_count INT NOT NULL DEFAULT 0,available_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_at DATETIME(6) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_outbox_pending(status,available_at,id),FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS system_settings (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,scope_type VARCHAR(40) NOT NULL,scope_id BIGINT UNSIGNED NOT NULL DEFAULT 0,`key` VARCHAR(160) NOT NULL,value_json JSON NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_system_setting(scope_type,scope_id,`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO plans(code,name,monthly_price,setup_fee,max_users,max_exchange_accounts,entitlements_json,status) VALUES ('starter','Starter',0,0,5,2,JSON_OBJECT('orders',true,'ads',true,'chat',true),'active');
